import os
import re
from datetime import datetime
from PIL import Image, ImageOps, ImageFilter
import pytesseract
from openpyxl import Workbook

IMG_DIR = '/app/workspace/dataset/img'
OUT_PATH = '/app/workspace/stat_ocr.xlsx'

EXCLUSION_KEYWORDS = [
    'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED'
]

PRIORITY_KEYWORDS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM', 'TOTAL RM:', 'TOTAL RM.'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT'],
]

MONTHS = {
    'JAN': 1, 'JANUARY': 1,
    'FEB': 2, 'FEBRUARY': 2,
    'MAR': 3, 'MARCH': 3,
    'APR': 4, 'APRIL': 4,
    'MAY': 5,
    'JUN': 6, 'JUNE': 6,
    'JUL': 7, 'JULY': 7,
    'AUG': 8, 'AUGUST': 8,
    'SEP': 9, 'SEPT': 9, 'SEPTEMBER': 9,
    'OCT': 10, 'OCTOBER': 10,
    'NOV': 11, 'NOVEMBER': 11,
    'DEC': 12, 'DECEMBER': 12,
}


def normalize_line(line: str) -> str:
    line = line.replace('\t', ' ')
    line = re.sub(r'\s+', ' ', line)
    return line.strip()


def preprocess_variants(img: Image.Image):
    variants = []
    base = img.convert('L')
    base = base.resize((base.width * 2, base.height * 2), Image.LANCZOS)
    variants.append(base)
    variants.append(ImageOps.autocontrast(base))
    variants.append(base.filter(ImageFilter.SHARPEN))
    variants.append(ImageOps.autocontrast(base.filter(ImageFilter.MedianFilter(3))))
    # simple threshold
    thresh = base.point(lambda x: 0 if x < 160 else 255, '1')
    variants.append(thresh)
    return variants


def ocr_texts(img_path: str):
    img = Image.open(img_path)
    texts = []
    for variant in preprocess_variants(img):
        try:
            text = pytesseract.image_to_string(variant, config='--oem 3 --psm 6')
        except Exception:
            continue
        if text and text not in texts:
            texts.append(text)
    return texts


def parse_amount_from_line(line: str):
    if not line:
        return None
    # normalize separators and spacing
    line = re.sub(r'\s*([,\.])\s*', r'\1', line)
    line = re.sub(r'(?<=\d)\s+(?=\d)', '', line)
    # prefer decimal amounts with 2 digits
    matches = re.findall(r'(\d{1,3}(?:,\d{3})*|\d+)\.(\d{2})', line)
    if matches:
        whole, frac = matches[-1]
        amount = whole.replace(',', '') + '.' + frac
        return f"{float(amount):.2f}"
    # fallback: integer amounts
    matches_int = re.findall(r'(\d{1,3}(?:,\d{3})*|\d+)', line)
    if matches_int:
        whole = matches_int[-1].replace(',', '')
        # avoid picking a year-like value if line doesn't look like currency
        if len(whole) == 4 and int(whole) >= 1900 and int(whole) <= 2099:
            return None
        try:
            return f"{float(whole):.2f}"
        except Exception:
            return None
    return None


def extract_total_from_text(text: str):
    lines = [normalize_line(l) for l in text.splitlines()]
    lines = [l for l in lines if l]
    upper_lines = [l.upper() for l in lines]
    for keyword_group in PRIORITY_KEYWORDS:
        for idx, uline in enumerate(upper_lines):
            if any(k in uline for k in EXCLUSION_KEYWORDS):
                continue
            if any(k in uline for k in keyword_group):
                amount = parse_amount_from_line(lines[idx])
                if amount:
                    return amount
                # fallback to next line
                if idx + 1 < len(lines):
                    amount = parse_amount_from_line(lines[idx + 1])
                    if amount:
                        return amount
    return None


def map_two_digit_year(y: int) -> int:
    return 2000 + y if y <= 79 else 1900 + y


def try_make_date(y: int, m: int, d: int):
    try:
        return datetime(y, m, d).date().isoformat()
    except Exception:
        return None


def extract_date_from_line(line: str):
    if not line:
        return None
    # YYYY-MM-DD or YYYY/MM/DD
    m = re.search(r'(\d{4})[\-/\.](\d{1,2})[\-/\.](\d{1,2})', line)
    if m:
        y, mo, d = map(int, m.groups())
        dt = try_make_date(y, mo, d)
        if dt:
            return dt
    # DD-MM-YYYY or MM-DD-YYYY or with 2-digit year
    m = re.search(r'(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{2,4})', line)
    if m:
        a, b, y = m.groups()
        a, b, y = int(a), int(b), int(y)
        if y < 100:
            y = map_two_digit_year(y)
        # decide order
        if a > 12 and b <= 12:
            d, mo = a, b
        elif b > 12 and a <= 12:
            mo, d = a, b
        else:
            # ambiguous, assume day/month
            d, mo = a, b
        dt = try_make_date(y, mo, d)
        if dt:
            return dt
    # YYYYMMDD
    m = re.search(r'\b(\d{4})(\d{2})(\d{2})\b', line)
    if m:
        y, mo, d = map(int, m.groups())
        dt = try_make_date(y, mo, d)
        if dt:
            return dt
    # DD MON YYYY
    m = re.search(r'\b(\d{1,2})\s*([A-Za-z]{3,9})\s*,?\s*(\d{2,4})\b', line)
    if m:
        d, mon_str, y = m.groups()
        mon_key = mon_str.strip().upper()
        if mon_key in MONTHS:
            d = int(d)
            y = int(y)
            if y < 100:
                y = map_two_digit_year(y)
            dt = try_make_date(y, MONTHS[mon_key], d)
            if dt:
                return dt
    # MON DD YYYY
    m = re.search(r'\b([A-Za-z]{3,9})\s*(\d{1,2})\s*,?\s*(\d{2,4})\b', line)
    if m:
        mon_str, d, y = m.groups()
        mon_key = mon_str.strip().upper()
        if mon_key in MONTHS:
            d = int(d)
            y = int(y)
            if y < 100:
                y = map_two_digit_year(y)
            dt = try_make_date(y, MONTHS[mon_key], d)
            if dt:
                return dt
    return None


def extract_date_from_text(text: str):
    lines = [normalize_line(l) for l in text.splitlines()]
    lines = [l for l in lines if l]
    for line in lines:
        dt = extract_date_from_line(line)
        if dt:
            return dt
    return None


def extract_fields(img_path: str):
    texts = ocr_texts(img_path)
    date_val = None
    total_val = None
    for text in texts:
        if not date_val:
            date_val = extract_date_from_text(text)
        if not total_val:
            total_val = extract_total_from_text(text)
        if date_val and total_val:
            break
    return date_val, total_val


files = [f for f in os.listdir(IMG_DIR) if os.path.isfile(os.path.join(IMG_DIR, f))]
files = sorted(files)

results = []
for fname in files:
    path = os.path.join(IMG_DIR, fname)
    date_val, total_val = extract_fields(path)
    results.append((fname, date_val, total_val))

wb = Workbook()
ws = wb.active
ws.title = 'results'
ws.append(['filename', 'date', 'total_amount'])
for row in results:
    ws.append(list(row))

wb.save(OUT_PATH)
print('wrote', OUT_PATH)
